// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {
        // deliberately gas-hungry receive: cannot run under the 2300 stipend
        for (uint256 i = 0; i < 1000; i++) {
            keccak256(abi.encode(i, address(c)));
        }
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "withdrawAll must revert: transfer stipend cannot satisfy the owner's gas-hungry receive");
    }
}
